<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Falling Sand — Cellular Automata Sandbox</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%}
  body{
    min-height:100vh;
    display:flex;align-items:center;justify-content:center;
    padding:24px;
    background:radial-gradient(1000px 700px at 50% -10%, #1a2030 0%, #0b0d12 55%);
    color:#e8eaf0;
    font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  }
  .app{display:flex;flex-direction:column;align-items:center;gap:16px}
  h1{font-size:20px;letter-spacing:.18em;text-transform:uppercase;font-weight:800}
  h1 em{color:#f2c14e;font-style:normal}
  .toolbar{
    display:flex;flex-wrap:wrap;justify-content:center;gap:8px;
    background:#151923;border:1px solid #262c3a;border-radius:14px;
    padding:10px 12px;box-shadow:0 10px 30px rgba(0,0,0,.35);
  }
  button{
    font:inherit;font-size:14px;color:#e8eaf0;background:#1d2330;border:1px solid #2c3342;
    border-radius:10px;padding:8px 14px;cursor:pointer;display:inline-flex;align-items:center;gap:8px;
    transition:background .15s,border-color .15s,box-shadow .15s,transform .05s;
    -webkit-user-select:none;user-select:none;
  }
  button:hover{background:#262e3f}
  button:active{transform:translateY(1px)}
  button .sw{width:12px;height:12px;border-radius:4px;background:var(--c,#888);box-shadow:0 0 8px var(--c,transparent)}
  button.active{border-color:#f2c14e;background:#2b2a1c;box-shadow:0 0 0 1px #f2c14e,0 0 14px rgba(242,193,78,.25)}
  #clear{background:#3a2026;border-color:#5b2b32}
  #clear:hover{background:#4d2930}
  .stage{background:#151923;border:1px solid #262c3a;border-radius:16px;padding:10px;box-shadow:0 24px 60px rgba(0,0,0,.55)}
  canvas{
    display:block;width:600px;height:600px;border-radius:8px;background:#111318;
    image-rendering:pixelated;image-rendering:crisp-edges;cursor:crosshair;touch-action:none;
  }
  .hint{color:#8b93a7;font-size:13px}
  kbd{background:#1d2330;border:1px solid #2c3342;border-bottom-width:2px;border-radius:5px;padding:0 6px;font-size:12px;font-family:inherit}
</style>
</head>
<body>
<div class="app">
  <h1>Falling <em>Sand</em></h1>
  <div class="toolbar">
    <button id="mat-sand" class="active"><span class="sw" style="--c:#e2b45e"></span>Sand</button>
    <button id="mat-water"><span class="sw" style="--c:#2f7fe1"></span>Water</button>
    <button id="mat-wall"><span class="sw" style="--c:#7b828f"></span>Wall</button>
    <button id="mat-acid"><span class="sw" style="--c:#4ae06b"></span>Acid</button>
    <button id="mat-empty"><span class="sw" style="--c:#111318"></span>Eraser</button>
    <button id="clear">&#10005; Clear</button>
  </div>
  <div class="stage"><canvas id="sand" width="120" height="120"></canvas></div>
  <p class="hint">Drag to paint &middot; <kbd>1</kbd>&ndash;<kbd>5</kbd> select material &middot; <kbd>C</kbd> clear</p>
</div>
<script>
(function(){
'use strict';

/* ================= Grid & materials ================= */
var W=120, H=120;                 // grid size in cells (>= 80x80)
var EMPTY=0, SAND=1, WATER=2, WALL=3, ACID=4;
var NAMES=['empty','sand','water','wall','acid'];
var CODE={empty:EMPTY, sand:SAND, water:WATER, wall:WALL, acid:ACID};

var grid  = new Uint8Array(W*H);  // cell -> material code
var stamp = new Int32Array(W*H);  // cell -> last stepId it moved (one move per step)
for(var i=0;i<stamp.length;i++) stamp[i]=-1;
var stepId=0;

/* ================= Rendering ================= */
var cv  = document.getElementById('sand');
var ctx = cv.getContext('2d');
var img = ctx.createImageData(W,H);
var shade = new Float32Array(W*H);           // fixed per-cell grain for texture
for(var s=0;s<shade.length;s++) shade[s]=0.84+Math.random()*0.28;
var PAL=[
  [ 17, 19, 24],   // empty
  [226,180, 94],   // sand
  [ 47,127,225],   // water
  [123,130,143],   // wall
  [ 74,224,107]    // acid
];

function render(){
  var d=img.data;
  for(var i=0;i<W*H;i++){
    var c=grid[i], p=PAL[c], o=i*4;
    if(c===EMPTY){ d[o]=p[0]; d[o+1]=p[1]; d[o+2]=p[2]; }
    else{
      var k=shade[i];
      d[o]=p[0]*k; d[o+1]=p[1]*k; d[o+2]=p[2]*k;
    }
    d[o+3]=255;
  }
  ctx.putImageData(img,0,0);
}

/* ================= Simulation ================= */
function isLiquid(c){ return c===WATER || c===ACID; }

/* Move particle from (x,y) to (nx,ny). If swap=true, may swap with a liquid
   that has NOT already moved this step (prevents liquid chain-rising). */
function tryMove(x,y,nx,ny,swap){
  if(nx<0||nx>=W||ny<0||ny>=H) return false;
  var i=y*W+x, j=ny*W+nx, t=grid[j];
  if(t===EMPTY){
    grid[j]=grid[i]; grid[i]=EMPTY;
    stamp[j]=stepId;
    return true;
  }
  if(swap && isLiquid(t) && stamp[j]!==stepId){
    grid[j]=grid[i]; grid[i]=t;      // sand sinks, liquid displaced locally by 1 cell
    stamp[j]=stepId; stamp[i]=stepId;
    return true;
  }
  return false;
}

function updateSand(x,y){
  if(y+1>=H) return;                              // bottom boundary: rest
  var i=y*W+x, b=grid[i+W];
  if(b===EMPTY || isLiquid(b)){                   // fall / sink straight down
    if(tryMove(x,y,x,y+1,true)) return;
  }
  var dx=Math.random()<0.5 ? -1 : 1;              // randomize first diagonal
  for(var k=0;k<2;k++){
    var nx=x+dx;
    if(nx>=0 && nx<W){
      var t=grid[(y+1)*W+nx];
      if(t===EMPTY || isLiquid(t)){
        if(tryMove(x,y,nx,y+1,true)) return;
      }
    }
    dx=-dx;
  }
}

/* Shared water/acid flow: down, then down-diagonals, then sideways (all into empty). */
function flow(x,y){
  var i=y*W+x, k, nx, dx;
  if(y+1<H && grid[i+W]===EMPTY){ tryMove(x,y,x,y+1,false); return; }
  if(y+1<H){
    dx=Math.random()<0.5 ? -1 : 1;
    for(k=0;k<2;k++){
      nx=x+dx;
      if(nx>=0 && nx<W && grid[(y+1)*W+nx]===EMPTY){ tryMove(x,y,nx,y+1,false); return; }
      dx=-dx;
    }
  }
  dx=Math.random()<0.5 ? -1 : 1;                  // randomize spread direction
  for(k=0;k<2;k++){
    nx=x+dx;
    if(nx>=0 && nx<W && grid[y*W+nx]===EMPTY){ tryMove(x,y,nx,y,false); return; }
    dx=-dx;
  }
}

function updateAcid(x,y){
  var i=y*W+x, t, opts=[];
  if(y+1<H){ t=grid[i+W]; if(t===SAND||t===WALL) opts.push(i+W); }
  if(x>0)  { t=grid[i-1]; if(t===SAND||t===WALL) opts.push(i-1); }
  if(x+1<W){ t=grid[i+1]; if(t===SAND||t===WALL) opts.push(i+1); }
  if(opts.length>0){                              // dissolve instead of moving
    var j=opts[(Math.random()*opts.length)|0];
    grid[j]=EMPTY;                                // target always erodes (walls erode)
    if(Math.random()<0.5) grid[i]=EMPTY;          // acid sometimes consumed
    stamp[i]=stepId;
    return;
  }
  flow(x,y);                                      // otherwise moves like water
}

/* One synchronous step: rows processed bottom-up so each particle moves <= 1 cell. */
function step(){
  stepId++;
  var ltr=(stepId&1)===0;                         // alternate sweep direction (no bias)
  for(var y=H-1;y>=0;y--){
    var row=y*W, x, i, c;
    if(ltr){
      for(x=0;x<W;x++){
        i=row+x;
        if(stamp[i]===stepId) continue;
        c=grid[i];
        if(c===SAND) updateSand(x,y);
        else if(c===WATER) flow(x,y);
        else if(c===ACID) updateAcid(x,y);
      }
    }else{
      for(x=W-1;x>=0;x--){
        i=row+x;
        if(stamp[i]===stepId) continue;
        c=grid[i];
        if(c===SAND) updateSand(x,y);
        else if(c===WATER) flow(x,y);
        else if(c===ACID) updateAcid(x,y);
      }
    }
  }
}

/* ================= Painting ================= */
var current=SAND, painting=false, lx=0, ly=0, BRUSH=3;

function canvasPos(e){
  var r=cv.getBoundingClientRect();
  return [
    Math.floor((e.clientX-r.left)/r.width *W),
    Math.floor((e.clientY-r.top )/r.height*H)
  ];
}
function paintAt(cx,cy){
  for(var dy=-BRUSH;dy<=BRUSH;dy++)for(var dx=-BRUSH;dx<=BRUSH;dx++){
    if(dx*dx+dy*dy>BRUSH*BRUSH+1) continue;
    var x=cx+dx, y=cy+dy;
    if(x>=0&&x<W&&y>=0&&y<H) grid[y*W+x]=current;
  }
}
function paintLine(x0,y0,x1,y1){
  var dx=x1-x0, dy=y1-y0, n=Math.max(Math.abs(dx),Math.abs(dy));
  if(n===0){ paintAt(x1,y1); return; }
  for(var s=0;s<=n;s++) paintAt(Math.round(x0+dx*s/n), Math.round(y0+dy*s/n));
}

cv.addEventListener('pointerdown',function(e){
  e.preventDefault();
  try{ cv.setPointerCapture(e.pointerId); }catch(_){}
  painting=true;
  var p=canvasPos(e); lx=p[0]; ly=p[1];
  paintAt(lx,ly);
});
cv.addEventListener('pointermove',function(e){
  if(!painting) return;
  var p=canvasPos(e);
  paintLine(lx,ly,p[0],p[1]);
  lx=p[0]; ly=p[1];
});
window.addEventListener('pointerup',function(){ painting=false; });
window.addEventListener('pointercancel',function(){ painting=false; });
cv.addEventListener('contextmenu',function(e){ e.preventDefault(); });

/* ================= Controls ================= */
var BTN={sand:'mat-sand', water:'mat-water', wall:'mat-wall', acid:'mat-acid', empty:'mat-empty'};
function select(name){
  current=CODE[name];
  for(var k in BTN) document.getElementById(BTN[k]).classList.toggle('active', k===name);
}
for(var key in BTN){
  (function(k){ document.getElementById(BTN[k]).addEventListener('click',function(){ select(k); }); })(key);
}
document.getElementById('clear').addEventListener('click',function(){ grid.fill(EMPTY); });
window.addEventListener('keydown',function(e){
  var map={'1':'sand','2':'water','3':'wall','4':'acid','5':'empty'};
  if(map[e.key]) select(map[e.key]);
  else if(e.key==='c'||e.key==='C') grid.fill(EMPTY);
});

/* ================= Programmatic API ================= */
window.sim={
  w:W,
  h:H,
  tick:function(n){
    n=(n===undefined)?1:Math.max(0,Math.floor(n));
    for(var k=0;k<n;k++) step();
    render();
  },
  get:function(x,y){
    x=Math.floor(x); y=Math.floor(y);
    if(!(x>=0&&x<W&&y>=0&&y<H)) return undefined;
    return NAMES[grid[y*W+x]];
  },
  set:function(x,y,m){
    var c=CODE[m];
    if(c===undefined) return;
    x=Math.floor(x); y=Math.floor(y);
    if(!(x>=0&&x<W&&y>=0&&y<H)) return;
    grid[y*W+x]=c;
  },
  clear:function(){ grid.fill(EMPTY); }
};

/* ================= Animation loop ================= */
function frame(){
  step(); step();                                 // 2 steps per frame for a lively sim
  render();
  requestAnimationFrame(frame);
}
render();
requestAnimationFrame(frame);

})();
</script>
</body>
</html>
